the Nazi persecution of men accused of homosexual acts; the memorial documents his death in January 1943.","source_url":"https://rosawinkelgedenkbuch.de/gedenken/w_klein.html","source_entity_id":"editorial-2026-09-22:wilhelm-klein","source_raw":{},"apply_identity":true,"clear_legacy_identity":false,"wikidata_qid":null,"wikidata_status":"not_found","profession":null,"nationality":"Germany","birth_date":"1904-09-25","death_date":"1943-01-09","is_living":false,"wikipedia_url":null,"clear_image":true},{"id":"64c82591-66a2-4fa0-820c-c1ab39a6798d","slug":"wilhelm-korner","cohort":"identity-remediation","description":"Wilhelm Körner was imprisoned at Sachsenhausen during the Nazi persecution of men accused of homosexual acts; the memorial documents his death in 1941.","source_url":"https://rosawinkelgedenkbuch.de/gedenken/w_koerner.html","source_entity_id":"editorial-2026-09-22:wilhelm-korner","source_raw":{},"apply_identity":true,"clear_legacy_identity":false,"wikidata_qid":null,"wikidata_status":"not_found","profession":null,"nationality":"Germany","birth_date":"1896-09-04","death_date":"1941-06-23","is_living":false,"wikipedia_url":null,"clear_image":true},{"id":"a8fd5767-f5db-48b2-b346-f455bc0c55c5","slug":"wilhelm-schafer","cohort":"identity-remediation","description":"Wilhelm Schäfer was imprisoned in the Ravensbrück men’s camp during the Nazi persecution of men accused of homosexual acts; the memorial records his death in 1943.","source_url":"https://rosawinkelgedenkbuch.de/gedenken/w_schaefer.html","source_entity_id":"editorial-2026-09-22:wilhelm-schafer","source_raw":{},"apply_identity":true,"clear_legacy_identity":false,"wikidata_qid":null,"wikidata_status":"not_found","profession":null,"nationality":"Germany","birth_date":"1892-02-01","death_date":"1943-04-28","is_living":false,"wikipedia_url":null,"clear_image":true},{"id":"7514f401-0671-44d1-84bf-a847e8cad68c","slug":"with-us","cohort":"whole-2026","description":"With Us appeared in the official WHOLE Festival 2026 programme as a collective, performing at 12:00 on 18 July on the Beach stage at Ferropolis, Germany.","source_url":"https://www.wholefestival.com/archive/de-en/2026/lineup/with-us","source_entity_id":"whole-2026:bc4c2cb5-275c-4b7d-befd-a14887002412:with-us","source_raw":{"official_artist_id":"bc4c2cb5-275c-4b7d-befd-a14887002412","official_title":"With Us","role":"Collective","slots":[{"area":"Beach","date":"2026-07-18","time":"12:00"}]},"apply_identity":false,"clear_legacy_identity":true,"wikidata_qid":null,"wikidata_status":null,"profession":"Collective","nationality":null,"birth_date":null,"death_date":null,"is_living":null,"wikipedia_url":null,"clear_image":false},{"id":"46c60695-ddd6-4307-8c20-8f5bf0efac2d","slug":"xheni-karaj","cohort":"encyclopedia","description":"Xheni Karaj is an Albanian LGBT rights activist, and co-founder and current executive of Aleanca LGBT organization. Xheni Karaj's career includes work as an activist in Albania.","source_url":"https://en.wikipedia.org/wiki/Xheni_Karaj","source_entity_id":"editorial-2026-09-22:xheni-karaj","source_raw":{"prior_source_id":"089a97cf-07f9-4218-bd18-832e260d6d08","wikidata_qid":"Q61079478"},"apply_identity":false,"clear_legacy_identity":false,"wikidata_qid":null,"wikidata_status":null,"profession":null,"nationality":null,"birth_date":null,"death_date":null,"is_living":null,"wikipedia_url":null,"clear_image":false},{"id":"e734e57e-9bed-4cf1-a46b-2db5ad48ecdf","slug":"yolanda-arroyo-pizarro","cohort":"encyclopedia","description":"Yolanda Arroyo Pizarro is a Puerto Rican novelist, short-story writer and essayist. Yolanda Arroyo Pizarro was born in 1970. Yolanda Arroyo Pizarro's career includes work as a writer in Puerto Rico.","source_url":"https://en.wikipedia.org/wiki/Yolanda_Arroyo_Pizarro","source_entity_id":"editorial-2026-09-22:yolanda-arroyo-pizarro","source_raw":{"prior_source_id":"b168e174-29ab-44bd-99e9-7ffe7d6dd886","wikidata_qid":"Q8054725"},"apply_identity":false,"clear_legacy_identity":false,"wikidata_qid":null,"wikidata_status":null,"profession":null,"nationality":null,"birth_date":null,"death_date":null,"is_living":null,"wikipedia_url":null,"clear_image":false},{"id":"1fc60a5c-fd34-4712-8e5b-291be8657ed3","slug":"zvuk","cohort":"whole-2026","description":"ZVUK appeared in the official WHOLE Festival 2026 programme as a collective, performing at 18:00 on 17 July on the Arena stage at Ferropolis, Germany.","source_url":"https://www.wholefestival.com/archive/de-en/2026/lineup/zvuk","source_entity_id":"whole-2026:d0fe1cd1-8a40-459c-bbf3-a31e849c52ac:zvuk","source_raw":{"official_artist_id":"d0fe1cd1-8a40-459c-bbf3-a31e849c52ac","official_title":"ZVUK","role":"Collective","slots":[{"area":"Arena","date":"2026-07-17","time":"18:00"}]},"apply_identity":false,"clear_legacy_identity":true,"wikidata_qid":null,"wikidata_status":null,"profession":"Collective","nationality":null,"birth_date":null,"death_date":null,"is_living":null,"wikipedia_url":null,"clear_image":false}]
$personality_editorial_payload$::jsonb) as u(
  id uuid,
  slug text,
  cohort text,
  description text,
  source_url text,
  source_entity_id text,
  source_raw jsonb,
  apply_identity boolean,
  clear_legacy_identity boolean,
  wikidata_qid text,
  wikidata_status text,
  profession text,
  nationality text,
  birth_date date,
  death_date date,
  is_living boolean,
  wikipedia_url text,
  clear_image boolean
);

do $$
declare v_count int;
begin
  select count(*) into v_count from personality_editorial_updates;
  if v_count <> 394 then
    raise exception 'expected 394 personality editorial updates, found %', v_count;
  end if;
  if exists (
    select 1 from personality_editorial_updates
    where length(btrim(description)) not between 120 and 240
       or source_url !~ '^https://'
       or source_entity_id is null
  ) then
    raise exception 'invalid editorial update contract';
  end if;
  if exists (
    select description from personality_editorial_updates
    group by description having count(*) > 1
  ) then
    raise exception 'duplicate editorial descriptions in staged batch';
  end if;
  if exists (
    select 1 from personality_editorial_updates u
    left join public.personalities p on p.id=u.id and p.slug=u.slug
    where p.id is null or p.visibility <> 'public' or p.duplicate_of_id is not null
      or coalesce(p.review_status,'') in ('archived','rejected')
  ) then
    raise exception 'staged personality identity or public state drifted';
  end if;
end $$;

insert into private.personality_remediation_audit
  (batch_key,personality_id,field_name,old_value,new_value,reason)
select 'personality-editorial-backlog-2026-09-22',p.id,v.field_name,v.old_value,v.new_value,v.reason
from public.personalities p
join personality_editorial_updates u on u.id=p.id
cross join lateral (values
  ('description',to_jsonb(p.description),to_jsonb(u.description),'replace thin or boilerplate text with a sourced 120-240 character summary'),
  ('wikidata_qid',to_jsonb(p.wikidata_qid),to_jsonb(case when u.apply_identity then u.wikidata_qid when u.clear_legacy_identity then null else p.wikidata_qid end),'repair exact-name entity collision'),
  ('wikidata_status',to_jsonb(p.wikidata_status),to_jsonb(case when u.apply_identity then u.wikidata_status when u.clear_legacy_identity then 'needs_review' else p.wikidata_status end),'align identifier state with reviewed identity'),
  ('profession',to_jsonb(p.profession),to_jsonb(case when u.apply_identity or u.clear_legacy_identity then u.profession else p.profession end),'repair field derived from a wrong entity match'),
  ('nationality',to_jsonb(p.nationality),to_jsonb(u.nationality),'repair field derived from a wrong entity match'),
  ('birth_date',to_jsonb(p.birth_date),to_jsonb(u.birth_date),'repair field derived from a wrong entity match'),
  ('death_date',to_jsonb(p.death_date),to_jsonb(u.death_date),'repair field derived from a wrong entity match'),
  ('is_living',to_jsonb(p.is_living),to_jsonb(u.is_living),'repair field derived from a wrong entity match'),
  ('bio',to_jsonb(p.bio),case when u.apply_identity or u.clear_legacy_identity then null::jsonb else to_jsonb(p.bio) end,'remove biography copied from a wrong entity match'),
  ('external_ids',to_jsonb(p.external_ids),case when u.apply_identity or u.clear_legacy_identity then '{}'::jsonb else to_jsonb(p.external_ids) end,'remove identifiers copied from a wrong entity match'),
  ('wikipedia_url',to_jsonb(p.wikipedia_url),case when u.apply_identity then to_jsonb(u.wikipedia_url) when u.clear_legacy_identity then null::jsonb else to_jsonb(p.wikipedia_url) end,'align article URL with reviewed identity'),
  ('image_url',to_jsonb(p.image_url),case when u.clear_image or (u.clear_legacy_identity and coalesce(p.image_url,'') ~* '(wikimedia|wikipedia|commons)') then null::jsonb else to_jsonb(p.image_url) end,'remove portrait belonging to a different person'),
  ('image_status',to_jsonb(p.image_status),case when u.clear_image or (u.clear_legacy_identity and coalesce(p.image_url,'') ~* '(wikimedia|wikipedia|commons)') then to_jsonb('unavailable'::text) else to_jsonb(p.image_status) end,'record safe explicit image absence after wrong portrait removal')
) as v(field_name,old_value,new_value,reason)
where (
    v.field_name='description'
    or (u.apply_identity and v.field_name in ('wikidata_qid','wikidata_status','profession','nationality','birth_date','death_date','is_living','bio','external_ids','wikipedia_url'))
    or (u.clear_legacy_identity and v.field_name in ('wikidata_qid','wikidata_status','profession','bio','external_ids','wikipedia_url'))
    or ((u.clear_image or (u.clear_legacy_identity and coalesce(p.image_url,'') ~* '(wikimedia|wikipedia|commons)')) and v.field_name in ('image_url','image_status'))
  )
  and v.old_value is distinct from v.new_value
on conflict do nothing;

-- Nina Westen is Ingrid Werner's stage name. Retire the draft alias before
-- assigning the reviewed QID to the canonical public profile.
insert into private.personality_remediation_audit
  (batch_key,personality_id,field_name,old_value,new_value,reason)
select 'personality-editorial-backlog-2026-09-22',alias.id,v.field_name,v.old_value,v.new_value,
  'retire duplicate stage-name profile in favour of canonical Ingrid Werner record'
from public.personalities alias
join public.personalities canonical on canonical.slug='ingrid-werner'
cross join lateral (values
  ('wikidata_qid',to_jsonb(alias.wikidata_qid),null::jsonb),
  ('wikidata_status',to_jsonb(alias.wikidata_status),to_jsonb('not_applicable'::text)),
  ('duplicate_of_id',to_jsonb(alias.duplicate_of_id),to_jsonb(canonical.id)),
  ('review_status',to_jsonb(alias.review_status),to_jsonb('archived'::text)),
  ('visibility',to_jsonb(alias.visibility),to_jsonb('draft'::text))
) as v(field_name,old_value,new_value)
where alias.slug='nina-westen' and v.old_value is distinct from v.new_value
on conflict do nothing;

update public.personalities alias
set wikidata_qid=null,
    wikidata_status='not_applicable',
    duplicate_of_id=canonical.id,
    review_status='archived',
    visibility='draft',
    seo_indexable=false,
    needs_attention=false,
    updated_at=now()
from public.personalities canonical
where alias.slug='nina-westen' and canonical.slug='ingrid-werner'
  and alias.id<>canonical.id;

update public.personality_sources s
set raw=coalesce(s.raw,'{}'::jsonb) || jsonb_build_object(
      'invalidated_at',now(),
      'invalidated_by','personality-editorial-backlog-2026-09-22',
      'reason','exact-name identity collision'
    ),
    is_primary=false,
    confidence=least(coalesce(s.confidence,0.5),0.1),
    last_seen_at=now()
from personality_editorial_updates u
where (u.apply_identity or u.clear_legacy_identity) and s.personality_id=u.id
  and s.source_slug in ('wikidata','wikipedia')
  and nullif(btrim(s.source_url),'') is distinct from u.source_url;

insert into public.personality_sources
  (personality_id,source_slug,source_entity_id,source_url,raw,confidence,is_primary,first_seen_at,last_seen_at)
select u.id,'editorial-remediation-2026-09-22',u.source_entity_id,u.source_url,
  coalesce(u.source_raw,'{}'::jsonb) || jsonb_build_object('cohort',u.cohort,'checked_at',now()),
  case when u.cohort='whole-2026' then 1.0 else 0.95 end,true,now(),now()
from personality_editorial_updates u
on conflict(source_slug,source_entity_id) do update
set personality_id=excluded.personality_id,
    source_url=excluded.source_url,
    raw=excluded.raw,
    confidence=excluded.confidence,
    is_primary=true,
    last_seen_at=excluded.last_seen_at;

insert into public.personality_claim_sources
  (personality_id,field_name,source_id,confidence,verification_status,checked_at)
select u.id,'description',s.id,s.confidence,'verified',now()
from personality_editorial_updates u
join public.personality_sources s
  on s.source_slug='editorial-remediation-2026-09-22'
 and s.source_entity_id=u.source_entity_id
on conflict(personality_id,field_name,source_id) do update
set confidence=excluded.confidence,
    verification_status='verified',
    checked_at=excluded.checked_at;

update public.personalities p
set description=u.description,
    wikidata_qid=case when u.apply_identity then u.wikidata_qid when u.clear_legacy_identity then null else p.wikidata_qid end,
    wikidata_status=case when u.apply_identity then u.wikidata_status when u.clear_legacy_identity then 'needs_review' else p.wikidata_status end,
    profession=case when u.apply_identity or u.clear_legacy_identity then u.profession else p.profession end,
    nationality=case when u.apply_identity then u.nationality else p.nationality end,
    birth_date=case when u.apply_identity then u.birth_date else p.birth_date end,
    death_date=case when u.apply_identity then u.death_date else p.death_date end,
    is_living=case when u.apply_identity then u.is_living else p.is_living end,
    bio=case when u.apply_identity or u.clear_legacy_identity then null else p.bio end,
    external_ids=case when u.apply_identity or u.clear_legacy_identity then '{}'::jsonb else p.external_ids end,
    wikipedia_url=case when u.apply_identity then u.wikipedia_url when u.clear_legacy_identity then null else p.wikipedia_url end,
    image_url=case when u.clear_image or (u.clear_legacy_identity and coalesce(p.image_url,'') ~* '(wikimedia|wikipedia|commons)') then null else p.image_url end,
    image_status=case when u.clear_image or (u.clear_legacy_identity and coalesce(p.image_url,'') ~* '(wikimedia|wikipedia|commons)') then 'unavailable' else p.image_status end,
    updated_at=now()
from personality_editorial_updates u
where p.id=u.id;

update public.entity_review_queue q
set status='approved',
    reviewer_note='Resolved by sourced editorial remediation batch 2026-09-22.',
    reviewed_at=now()
from personality_editorial_updates u
where q.entity_type='personality' and q.entity_id=u.id
  and q.field='description' and q.status='open';

update public.entity_review_queue q
set status='superseded',
    reviewer_note='Wrong-identity portrait removed by remediation batch 2026-09-22.',
    reviewed_at=now()
from personality_editorial_updates u
where (u.clear_image or exists (
    select 1 from private.personality_remediation_audit a
    where a.batch_key='personality-editorial-backlog-2026-09-22'
      and a.personality_id=u.id and a.field_name='image_url'
  )) and q.entity_type='personality' and q.entity_id=u.id
  and q.field='image_url' and q.status='open';

with calculated as materialized (
  select p.id,public.compute_personality_quality_dimensions(p.id) dims
  from public.personalities p
  join personality_editorial_updates u on u.id=p.id
)
update public.personalities p
set quality_score=(c.dims->>'score')::smallint,
    quality_score_version=2,
    quality_dimensions=c.dims,
    quality_evaluated_at=now()
from calculated c
where p.id=c.id;

do $$
declare v_gate record;
begin
  if exists (
    select 1 from personality_editorial_updates u
    join public.personalities p on p.id=u.id
    where length(btrim(p.description)) not between 120 and 240
       or lower(regexp_replace(btrim(p.description),'\s+',' ','g')) = lower(regexp_replace(btrim(coalesce(p.bio,'')),'\s+',' ','g'))
  ) then
    raise exception 'summary contract failed after editorial update';
  end if;
  if exists (
    select 1 from personality_editorial_updates u
    where not exists (
      select 1 from public.personality_claim_sources cs
      join public.personality_sources s on s.id=cs.source_id
      where cs.personality_id=u.id and cs.field_name='description'
        and cs.verification_status='verified'
        and s.source_slug='editorial-remediation-2026-09-22'
    )
  ) then
    raise exception 'verified description provenance missing after editorial update';
  end if;
  if exists (
    select 1 from public.entity_review_queue q
    join personality_editorial_updates u on u.id=q.entity_id
    where q.entity_type='personality' and q.field='description' and q.status='open'
  ) then
    raise exception 'resolved description review remains open';
  end if;
  if exists (
    select 1 from public.personalities
    where visibility='public' and description='Performer at WHOLE Festival 2026 (Ferropolis, Germany).'
  ) then
    raise exception 'WHOLE Festival boilerplate remains public';
  end if;
  for v_gate in select * from public.personality_quality_gate_checks() loop
    if v_gate.failures <> 0 then
      raise exception 'personality quality gate % still has % failures',v_gate.gate,v_gate.failures;
    end if;
  end loop;
end $$;

commit;
